import{_ as l,H as e,f as i,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"第二法典","description":"","frontmatter":{"title":"第二法典","outline":"deep"},"headers":[],"relativePath":"rules2.md","filePath":"rules2.md"}'),o={name:"rules2.md"};function h(t,a,n,d,s,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第二法典" tabindex="-1">第二法典 <a class="header-anchor" href="#第二法典" aria-label="Permalink to &quot;第二法典&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PIGLIN KINGDOM 大法典 第二法典（第51条～第100条）</p></div><h1 id="第十八編-医療法" tabindex="-1">第十八編 医療法 <a class="header-anchor" href="#第十八編-医療法" aria-label="Permalink to &quot;第十八編 医療法&quot;">​</a></h1><h2 id="第一章-医療制度" tabindex="-1">第一章 医療制度 <a class="header-anchor" href="#第一章-医療制度" aria-label="Permalink to &quot;第一章 医療制度&quot;">​</a></h2><h3 id="第51条-医療サービス" tabindex="-1">第51条 医療サービス <a class="header-anchor" href="#第51条-医療サービス" aria-label="Permalink to &quot;第51条 医療サービス&quot;">​</a></h3><ol><li>王国は国民に医療サービスを提供する。</li><li>各州に王立病院を設置する。</li><li>緊急患者を優先的に治療する。</li></ol><h3 id="第52条-医師" tabindex="-1">第52条 医師 <a class="header-anchor" href="#第52条-医師" aria-label="Permalink to &quot;第52条 医師&quot;">​</a></h3><ol><li>医師免許を有する者のみ医療行為を行える。</li><li>無資格医療を禁ずる。</li></ol><h3 id="第53条-ポーション医療" tabindex="-1">第53条 ポーション医療 <a class="header-anchor" href="#第53条-ポーション医療" aria-label="Permalink to &quot;第53条 ポーション医療&quot;">​</a></h3><ol><li>回復ポーションは医療行為として認める。</li><li>毒のポーションを不法目的で使用してはならない。</li></ol><h3 id="第54条-王立救急隊" tabindex="-1">第54条 王立救急隊 <a class="header-anchor" href="#第54条-王立救急隊" aria-label="Permalink to &quot;第54条 王立救急隊&quot;">​</a></h3><ol><li>王立救急隊を設置する。</li><li>災害時には軍と協力する。</li></ol><hr><h1 id="第十九編-労働法" tabindex="-1">第十九編 労働法 <a class="header-anchor" href="#第十九編-労働法" aria-label="Permalink to &quot;第十九編 労働法&quot;">​</a></h1><h2 id="第一章-労働" tabindex="-1">第一章 労働 <a class="header-anchor" href="#第一章-労働" aria-label="Permalink to &quot;第一章 労働&quot;">​</a></h2><h3 id="第55条-職業選択の自由" tabindex="-1">第55条 職業選択の自由 <a class="header-anchor" href="#第55条-職業選択の自由" aria-label="Permalink to &quot;第55条 職業選択の自由&quot;">​</a></h3><ol><li>国民は自由に職業を選択できる。</li><li>奴隷制度を禁ずる。</li></ol><h3 id="第56条-労働時間" tabindex="-1">第56条 労働時間 <a class="header-anchor" href="#第56条-労働時間" aria-label="Permalink to &quot;第56条 労働時間&quot;">​</a></h3><ol><li>標準労働時間は1日8時間とする。</li><li>時間外労働には補償を行う。</li></ol><h3 id="第57条-労働安全" tabindex="-1">第57条 労働安全 <a class="header-anchor" href="#第57条-労働安全" aria-label="Permalink to &quot;第57条 労働安全&quot;">​</a></h3><ol><li>雇用者は安全を確保しなければならない。</li><li>溶岩付近で働く者には耐火装備を支給する。</li></ol><h3 id="第58条-休日" tabindex="-1">第58条 休日 <a class="header-anchor" href="#第58条-休日" aria-label="Permalink to &quot;第58条 休日&quot;">​</a></h3><ol><li>毎週2日の休日を設ける。</li><li>黄金祭は祝日とする。</li></ol><hr><h1 id="第二十編-銀行法" tabindex="-1">第二十編 銀行法 <a class="header-anchor" href="#第二十編-銀行法" aria-label="Permalink to &quot;第二十編 銀行法&quot;">​</a></h1><h2 id="第一章-王立銀行" tabindex="-1">第一章 王立銀行 <a class="header-anchor" href="#第一章-王立銀行" aria-label="Permalink to &quot;第一章 王立銀行&quot;">​</a></h2><h3 id="第59条-王立銀行" tabindex="-1">第59条 王立銀行 <a class="header-anchor" href="#第59条-王立銀行" aria-label="Permalink to &quot;第59条 王立銀行&quot;">​</a></h3><ol><li>王立黄金銀行を設置する。</li><li>通貨発行を管理する。</li></ol><h3 id="第60条-預金" tabindex="-1">第60条 預金 <a class="header-anchor" href="#第60条-預金" aria-label="Permalink to &quot;第60条 預金&quot;">​</a></h3><ol><li>国民は銀行口座を保有できる。</li><li>預金は法によって保護される。</li></ol><h3 id="第61条-融資" tabindex="-1">第61条 融資 <a class="header-anchor" href="#第61条-融資" aria-label="Permalink to &quot;第61条 融資&quot;">​</a></h3><ol><li>銀行は融資を行える。</li><li>年利は10パーセントを超えてはならない。</li></ol><h3 id="第62条-偽造通貨" tabindex="-1">第62条 偽造通貨 <a class="header-anchor" href="#第62条-偽造通貨" aria-label="Permalink to &quot;第62条 偽造通貨&quot;">​</a></h3><ol><li>偽造通貨を禁ずる。</li><li>偽造通貨は没収する。</li></ol><hr><h1 id="第二十一編-郵便法" tabindex="-1">第二十一編 郵便法 <a class="header-anchor" href="#第二十一編-郵便法" aria-label="Permalink to &quot;第二十一編 郵便法&quot;">​</a></h1><h2 id="第一章-郵便制度" tabindex="-1">第一章 郵便制度 <a class="header-anchor" href="#第一章-郵便制度" aria-label="Permalink to &quot;第一章 郵便制度&quot;">​</a></h2><h3 id="第63条-王立郵便" tabindex="-1">第63条 王立郵便 <a class="header-anchor" href="#第63条-王立郵便" aria-label="Permalink to &quot;第63条 王立郵便&quot;">​</a></h3><ol><li>王立郵便制度を設置する。</li><li>全国に支局を配置する。</li></ol><h3 id="第64条-秘密保持" tabindex="-1">第64条 秘密保持 <a class="header-anchor" href="#第64条-秘密保持" aria-label="Permalink to &quot;第64条 秘密保持&quot;">​</a></h3><ol><li>郵便職員は秘密を守らなければならない。</li><li>無断で郵便物を開封してはならない。</li></ol><h3 id="第65条-優先配送" tabindex="-1">第65条 優先配送 <a class="header-anchor" href="#第65条-優先配送" aria-label="Permalink to &quot;第65条 優先配送&quot;">​</a></h3><ol><li>王命は最優先で輸送する。</li><li>緊急輸送には特別なストライダーを使用できる。</li></ol><hr><h1 id="第二十二編-通信法" tabindex="-1">第二十二編 通信法 <a class="header-anchor" href="#第二十二編-通信法" aria-label="Permalink to &quot;第二十二編 通信法&quot;">​</a></h1><h2 id="第一章-通信" tabindex="-1">第一章 通信 <a class="header-anchor" href="#第一章-通信" aria-label="Permalink to &quot;第一章 通信&quot;">​</a></h2><h3 id="第66条-通信の自由" tabindex="-1">第66条 通信の自由 <a class="header-anchor" href="#第66条-通信の自由" aria-label="Permalink to &quot;第66条 通信の自由&quot;">​</a></h3><ol><li>国民は通信の自由を有する。</li><li>国家機密を除き通信内容は保護される。</li></ol><h3 id="第67条-通信網" tabindex="-1">第67条 通信網 <a class="header-anchor" href="#第67条-通信網" aria-label="Permalink to &quot;第67条 通信網&quot;">​</a></h3><ol><li>レッドストーン通信網を整備する。</li><li>設備の破壊を禁ずる。</li></ol><h3 id="第68条-虚偽情報" tabindex="-1">第68条 虚偽情報 <a class="header-anchor" href="#第68条-虚偽情報" aria-label="Permalink to &quot;第68条 虚偽情報&quot;">​</a></h3><ol><li>故意に虚偽情報を流してはならない。</li><li>災害時の虚偽通報は重大犯罪とする。</li></ol><hr><h1 id="第二十三編-海事法" tabindex="-1">第二十三編 海事法 <a class="header-anchor" href="#第二十三編-海事法" aria-label="Permalink to &quot;第二十三編 海事法&quot;">​</a></h1><h2 id="第一章-船舶" tabindex="-1">第一章 船舶 <a class="header-anchor" href="#第一章-船舶" aria-label="Permalink to &quot;第一章 船舶&quot;">​</a></h2><h3 id="第69条-船舶登録" tabindex="-1">第69条 船舶登録 <a class="header-anchor" href="#第69条-船舶登録" aria-label="Permalink to &quot;第69条 船舶登録&quot;">​</a></h3><ol><li>船舶は登録を要する。</li><li>船長は免許を有しなければならない。</li></ol><h3 id="第70条-海賊行為" tabindex="-1">第70条 海賊行為 <a class="header-anchor" href="#第70条-海賊行為" aria-label="Permalink to &quot;第70条 海賊行為&quot;">​</a></h3><ol><li>海賊行為を禁ずる。</li><li>王立海軍は海賊を鎮圧する。</li></ol><h3 id="第71条-海難救助" tabindex="-1">第71条 海難救助 <a class="header-anchor" href="#第71条-海難救助" aria-label="Permalink to &quot;第71条 海難救助&quot;">​</a></h3><ol><li>救助活動を優先する。</li><li>救助者には報奨を与える。</li></ol><hr><h1 id="第二十四編-航空法" tabindex="-1">第二十四編 航空法 <a class="header-anchor" href="#第二十四編-航空法" aria-label="Permalink to &quot;第二十四編 航空法&quot;">​</a></h1><h2 id="第一章-飛行" tabindex="-1">第一章 飛行 <a class="header-anchor" href="#第一章-飛行" aria-label="Permalink to &quot;第一章 飛行&quot;">​</a></h2><h3 id="第72条-飛空艇" tabindex="-1">第72条 飛空艇 <a class="header-anchor" href="#第72条-飛空艇" aria-label="Permalink to &quot;第72条 飛空艇&quot;">​</a></h3><ol><li>飛空艇は登録を要する。</li><li>首都上空の飛行には許可を必要とする。</li></ol><h3 id="第73条-エリトラ飛行" tabindex="-1">第73条 エリトラ飛行 <a class="header-anchor" href="#第73条-エリトラ飛行" aria-label="Permalink to &quot;第73条 エリトラ飛行&quot;">​</a></h3><ol><li>エリトラによる飛行を認める。</li><li>軍事空域への侵入を禁ずる。</li></ol><h3 id="第74条-航空事故" tabindex="-1">第74条 航空事故 <a class="header-anchor" href="#第74条-航空事故" aria-label="Permalink to &quot;第74条 航空事故&quot;">​</a></h3><ol><li>事故発生時は報告を行う。</li><li>調査委員会を設置する。</li></ol><hr><h1 id="第二十五編-漁業法" tabindex="-1">第二十五編 漁業法 <a class="header-anchor" href="#第二十五編-漁業法" aria-label="Permalink to &quot;第二十五編 漁業法&quot;">​</a></h1><h2 id="第一章-漁業" tabindex="-1">第一章 漁業 <a class="header-anchor" href="#第一章-漁業" aria-label="Permalink to &quot;第一章 漁業&quot;">​</a></h2><h3 id="第75条-漁業権" tabindex="-1">第75条 漁業権 <a class="header-anchor" href="#第75条-漁業権" aria-label="Permalink to &quot;第75条 漁業権&quot;">​</a></h3><ol><li>漁業には許可を要する。</li><li>幼魚を保護する。</li></ol><h3 id="第76条-禁漁期間" tabindex="-1">第76条 禁漁期間 <a class="header-anchor" href="#第76条-禁漁期間" aria-label="Permalink to &quot;第76条 禁漁期間&quot;">​</a></h3><ol><li>禁漁期間を設けることができる。</li><li>違反者には罰金を科す。</li></ol><hr><h1 id="第二十六編-交通法" tabindex="-1">第二十六編 交通法 <a class="header-anchor" href="#第二十六編-交通法" aria-label="Permalink to &quot;第二十六編 交通法&quot;">​</a></h1><h2 id="第一章-交通" tabindex="-1">第一章 交通 <a class="header-anchor" href="#第一章-交通" aria-label="Permalink to &quot;第一章 交通&quot;">​</a></h2><h3 id="第77条-通行" tabindex="-1">第77条 通行 <a class="header-anchor" href="#第77条-通行" aria-label="Permalink to &quot;第77条 通行&quot;">​</a></h3><ol><li>左側通行とする。</li><li>緊急車両を優先する。</li></ol><h3 id="第78条-馬車" tabindex="-1">第78条 馬車 <a class="header-anchor" href="#第78条-馬車" aria-label="Permalink to &quot;第78条 馬車&quot;">​</a></h3><ol><li>夜間走行時にはランタンを点灯する。</li></ol><h3 id="第79条-ストライダー" tabindex="-1">第79条 ストライダー <a class="header-anchor" href="#第79条-ストライダー" aria-label="Permalink to &quot;第79条 ストライダー&quot;">​</a></h3><ol><li>運転には免許を必要とする。</li><li>幼体への過積載を禁ずる。</li></ol><hr><h1 id="第二十七編-防災法" tabindex="-1">第二十七編 防災法 <a class="header-anchor" href="#第二十七編-防災法" aria-label="Permalink to &quot;第二十七編 防災法&quot;">​</a></h1><h2 id="第一章-災害対策" tabindex="-1">第一章 災害対策 <a class="header-anchor" href="#第一章-災害対策" aria-label="Permalink to &quot;第一章 災害対策&quot;">​</a></h2><h3 id="第80条-王立防災庁" tabindex="-1">第80条 王立防災庁 <a class="header-anchor" href="#第80条-王立防災庁" aria-label="Permalink to &quot;第80条 王立防災庁&quot;">​</a></h3><ol><li>王立防災庁を設置する。</li><li>火災・洪水・侵略に対応する。</li></ol><h3 id="第81条-避難" tabindex="-1">第81条 避難 <a class="header-anchor" href="#第81条-避難" aria-label="Permalink to &quot;第81条 避難&quot;">​</a></h3><ol><li>避難所を整備する。</li><li>非常食を備蓄する。</li></ol><h3 id="第82条-警報" tabindex="-1">第82条 警報 <a class="header-anchor" href="#第82条-警報" aria-label="Permalink to &quot;第82条 警報&quot;">​</a></h3><ol><li>警報塔を建設する。</li><li>国民は避難命令に従わなければならない。</li></ol><hr><h1 id="第二十八編-文化財保護法" tabindex="-1">第二十八編 文化財保護法 <a class="header-anchor" href="#第二十八編-文化財保護法" aria-label="Permalink to &quot;第二十八編 文化財保護法&quot;">​</a></h1><h2 id="第一章-文化財" tabindex="-1">第一章 文化財 <a class="header-anchor" href="#第一章-文化財" aria-label="Permalink to &quot;第一章 文化財&quot;">​</a></h2><h3 id="第83条-古代遺跡" tabindex="-1">第83条 古代遺跡 <a class="header-anchor" href="#第83条-古代遺跡" aria-label="Permalink to &quot;第83条 古代遺跡&quot;">​</a></h3><ol><li>古代遺跡を保護する。</li><li>無断破壊を禁ずる。</li></ol><h3 id="第84条-芸術品" tabindex="-1">第84条 芸術品 <a class="header-anchor" href="#第84条-芸術品" aria-label="Permalink to &quot;第84条 芸術品&quot;">​</a></h3><ol><li>王立博物館を設置する。</li><li>歴史的宝物を保存する。</li></ol><hr><h1 id="第二十九編-動物保護法" tabindex="-1">第二十九編 動物保護法 <a class="header-anchor" href="#第二十九編-動物保護法" aria-label="Permalink to &quot;第二十九編 動物保護法&quot;">​</a></h1><h2 id="第一章-動物" tabindex="-1">第一章 動物 <a class="header-anchor" href="#第一章-動物" aria-label="Permalink to &quot;第一章 動物&quot;">​</a></h2><h3 id="第85条-保護動物" tabindex="-1">第85条 保護動物 <a class="header-anchor" href="#第85条-保護動物" aria-label="Permalink to &quot;第85条 保護動物&quot;">​</a></h3><ol><li>ストライダーを保護動物とする。</li><li>幼いホグリンへの虐待を禁ずる。</li></ol><h3 id="第86条-飼育" tabindex="-1">第86条 飼育 <a class="header-anchor" href="#第86条-飼育" aria-label="Permalink to &quot;第86条 飼育&quot;">​</a></h3><ol><li>家畜に適切な餌を与えなければならない。</li><li>遺棄を禁ずる。</li></ol><hr><h1 id="第三十編-高等教育法" tabindex="-1">第三十編 高等教育法 <a class="header-anchor" href="#第三十編-高等教育法" aria-label="Permalink to &quot;第三十編 高等教育法&quot;">​</a></h1><h2 id="第一章-大学" tabindex="-1">第一章 大学 <a class="header-anchor" href="#第一章-大学" aria-label="Permalink to &quot;第一章 大学&quot;">​</a></h2><h3 id="第87条-王立大学" tabindex="-1">第87条 王立大学 <a class="header-anchor" href="#第87条-王立大学" aria-label="Permalink to &quot;第87条 王立大学&quot;">​</a></h3><ol><li>王立大学を設置する。</li><li>学術研究を奨励する。</li></ol><h3 id="第88条-奨学金" tabindex="-1">第88条 奨学金 <a class="header-anchor" href="#第88条-奨学金" aria-label="Permalink to &quot;第88条 奨学金&quot;">​</a></h3><ol><li>優秀な学生に奨学金を支給する。</li><li>貧困によって教育機会を失わせてはならない。</li></ol><hr><h1 id="第三十一編-科学研究法" tabindex="-1">第三十一編 科学研究法 <a class="header-anchor" href="#第三十一編-科学研究法" aria-label="Permalink to &quot;第三十一編 科学研究法&quot;">​</a></h1><h2 id="第一章-研究機関" tabindex="-1">第一章 研究機関 <a class="header-anchor" href="#第一章-研究機関" aria-label="Permalink to &quot;第一章 研究機関&quot;">​</a></h2><h3 id="第89条-王立研究院" tabindex="-1">第89条 王立研究院 <a class="header-anchor" href="#第89条-王立研究院" aria-label="Permalink to &quot;第89条 王立研究院&quot;">​</a></h3><ol><li>王立研究院を設置する。</li><li>技術開発を支援する。</li></ol><h3 id="第90条-発明者" tabindex="-1">第90条 発明者 <a class="header-anchor" href="#第90条-発明者" aria-label="Permalink to &quot;第90条 発明者&quot;">​</a></h3><ol><li>発明者を国家が表彰できる。</li><li>特許権は20年間保護される。</li></ol><hr><h1 id="第三十二編-国勢調査法" tabindex="-1">第三十二編 国勢調査法 <a class="header-anchor" href="#第三十二編-国勢調査法" aria-label="Permalink to &quot;第三十二編 国勢調査法&quot;">​</a></h1><h2 id="第一章-統計" tabindex="-1">第一章 統計 <a class="header-anchor" href="#第一章-統計" aria-label="Permalink to &quot;第一章 統計&quot;">​</a></h2><h3 id="第91条-国勢調査" tabindex="-1">第91条 国勢調査 <a class="header-anchor" href="#第91条-国勢調査" aria-label="Permalink to &quot;第91条 国勢調査&quot;">​</a></h3><ol><li>10年ごとに国勢調査を実施する。</li><li>行政運営に活用する。</li></ol><h3 id="第92条-統計局" tabindex="-1">第92条 統計局 <a class="header-anchor" href="#第92条-統計局" aria-label="Permalink to &quot;第92条 統計局&quot;">​</a></h3><ol><li>王立統計局を設置する。</li><li>統計の改ざんを禁ずる。</li></ol><hr><h1 id="第三十三編-スポーツ法" tabindex="-1">第三十三編 スポーツ法 <a class="header-anchor" href="#第三十三編-スポーツ法" aria-label="Permalink to &quot;第三十三編 スポーツ法&quot;">​</a></h1><h2 id="第一章-国技" tabindex="-1">第一章 国技 <a class="header-anchor" href="#第一章-国技" aria-label="Permalink to &quot;第一章 国技&quot;">​</a></h2><h3 id="第93条-国技" tabindex="-1">第93条 国技 <a class="header-anchor" href="#第93条-国技" aria-label="Permalink to &quot;第93条 国技&quot;">​</a></h3><ol><li>ホグリン競走を国技とする。</li><li>弓術大会を奨励する。</li></ol><h3 id="第94条-黄金祭大会" tabindex="-1">第94条 黄金祭大会 <a class="header-anchor" href="#第94条-黄金祭大会" aria-label="Permalink to &quot;第94条 黄金祭大会&quot;">​</a></h3><ol><li>毎年黄金祭大会を開催する。</li></ol><hr><h1 id="第三十四編-観光法" tabindex="-1">第三十四編 観光法 <a class="header-anchor" href="#第三十四編-観光法" aria-label="Permalink to &quot;第三十四編 観光法&quot;">​</a></h1><h2 id="第一章-観光" tabindex="-1">第一章 観光 <a class="header-anchor" href="#第一章-観光" aria-label="Permalink to &quot;第一章 観光&quot;">​</a></h2><h3 id="第95条-来訪者" tabindex="-1">第95条 来訪者 <a class="header-anchor" href="#第95条-来訪者" aria-label="Permalink to &quot;第95条 来訪者&quot;">​</a></h3><ol><li>外国人来訪者を歓迎する。</li><li>王国の習慣を尊重しなければならない。</li></ol><h3 id="第96条-宿屋" tabindex="-1">第96条 宿屋 <a class="header-anchor" href="#第96条-宿屋" aria-label="Permalink to &quot;第96条 宿屋&quot;">​</a></h3><ol><li>宿屋営業には許可を必要とする。</li></ol><hr><h1 id="第三十五編-気象法" tabindex="-1">第三十五編 気象法 <a class="header-anchor" href="#第三十五編-気象法" aria-label="Permalink to &quot;第三十五編 気象法&quot;">​</a></h1><h2 id="第一章-気象観測" tabindex="-1">第一章 気象観測 <a class="header-anchor" href="#第一章-気象観測" aria-label="Permalink to &quot;第一章 気象観測&quot;">​</a></h2><h3 id="第97条-王立気象局" tabindex="-1">第97条 王立気象局 <a class="header-anchor" href="#第97条-王立気象局" aria-label="Permalink to &quot;第97条 王立気象局&quot;">​</a></h3><ol><li>王立気象局を設置する。</li><li>予報及び警報を発表する。</li></ol><h3 id="第98条-観測塔" tabindex="-1">第98条 観測塔 <a class="header-anchor" href="#第98条-観測塔" aria-label="Permalink to &quot;第98条 観測塔&quot;">​</a></h3><ol><li>各州に観測塔を建設する。</li></ol><hr><h1 id="第三十六編-栄典法" tabindex="-1">第三十六編 栄典法 <a class="header-anchor" href="#第三十六編-栄典法" aria-label="Permalink to &quot;第三十六編 栄典法&quot;">​</a></h1><h2 id="第一章-勲章" tabindex="-1">第一章 勲章 <a class="header-anchor" href="#第一章-勲章" aria-label="Permalink to &quot;第一章 勲章&quot;">​</a></h2><h3 id="第99条-黄金勲章" tabindex="-1">第99条 黄金勲章 <a class="header-anchor" href="#第99条-黄金勲章" aria-label="Permalink to &quot;第99条 黄金勲章&quot;">​</a></h3><ol><li>国家への功績に対して授与する。</li><li>国王が親授できる。</li></ol><h3 id="第100条-名誉国民" tabindex="-1">第100条 名誉国民 <a class="header-anchor" href="#第100条-名誉国民" aria-label="Permalink to &quot;第100条 名誉国民&quot;">​</a></h3><ol><li>特別な功績を持つ者を名誉国民とする。</li><li>名誉国民は王国の保護を受ける。</li></ol>',158)])])}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
